// The python backend (docs/spec/fsm.md, B-4 and B-6; docs/plans/fsm-v1/plan.md, C-2): the generated files of the python package
// `src/polyspec_fsm/` (<machine>.py for every machine, fsm.py and __init__.py) and the native vector module
// `tests/vectors.py`. It takes the IRs of the machines (normalize.mjs), in definition order, and the lock, and returns the text of
// every file; it writes nothing. The output is deterministic: declaration order, four spaces of indentation, double quotes and a
// final line break. The generated code has no runtime dependency: it uses the standard library only (enum, dataclasses).
//
// Notation (B-6): State and Event are IntEnum classes whose members are upper case (State.DRAFT, Event.NEXT); Step is a frozen
// dataclass with the fields to and changed; Code is a StrEnum whose members are the error codes without E_ (Code.CONFLICT), whose
// values keep the E_ prefix. The functions take the state and event values in the order of B-6 and raise fsm.Error only.

import { forKind } from '../core/vectors.mjs';

const SHARED = 'fsm';
const KIND = 'python';

/** The member name of a key: the upper notation of B-6. Keys match ^[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*$, so this is one-to-one. */
const upper = key => key.toUpperCase();

/** The first line of a generated file (docs/spec/fsm.md, B-6), in the comment syntax of python. */
const header = from => `# Code generated by fsm-gen from ${from}; DO NOT EDIT.`;

/** The text of a list of lines: each line ends with a line break. */
const text = lines => `${lines.join('\n')}\n`;

/** A JavaScript string as a python double-quoted string; the keys and messages of a definition hold no quote or backslash. */
const quoted = value => `"${value}"`;

/** A message of the generated code: the literal text with one `%s` for each value, which str() formats, and the values in a tuple. The
 * literal holds the name of a machine or a state key, which are identifiers, so it needs no escape of `%`. */
const message = (literal, values) => `${quoted(literal)} % (${values.length === 1 ? `${values[0]},` : values.join(', ')})`;

/** The shared module: the error codes of B-4, B-5 and B-6 that the functions raise, and the Error of every machine. */
const FSM_PY = text([
  header(SHARED),
  '"""The error codes that the functions of every machine raise, and their Error (docs/spec/fsm.md, B-4 and B-6)."""',
  '',
  'from enum import StrEnum',
  '',
  '',
  'class Code(StrEnum):',
  '    """The error codes that the functions of every machine raise (docs/spec/fsm.md, B-4 and B-6)."""',
  '',
  '    CONFLICT = "E_CONFLICT"',
  '    INVALID_TRANSITION = "E_INVALID_TRANSITION"',
  '    UNKNOWN_CODE = "E_UNKNOWN_CODE"',
  '    RESERVED_CODE = "E_RESERVED_CODE"',
  '',
  '',
  'class Error(Exception):',
  '    """The error of a machine function. The fields hold the arguments of apply or target that failed; the others are None."""',
  '',
  '    def __init__(self, code, message, *, expected=None, actual=None, event=None):',
  '        super().__init__(message)',
  '        self.code = code',
  '        self.expected = expected',
  '        self.actual = actual',
  '        self.event = event',
]);

/** The package module: the machine modules and the shared module, in the order of the definitions. */
function initJs(irs) {
  const names = [...irs.map(ir => ir.machine), SHARED];
  return text([
    header(SHARED),
    '"""The generated package of fsm: one module per machine, and the shared module fsm."""',
    '',
    `from . import ${names.join(', ')}`,
    '',
    `__all__ = [${names.map(name => quoted(name)).join(', ')}]`,
  ]);
}

/** The machine module of `ir` with its reserved codes from `lock`: the enums, Step and the functions of B-6, in that order. */
function machinePy(ir, lock) {
  const { machine, initial, states, events, transitions } = ir;
  const reserved = [...lock[machine].reserved].sort((a, b) => a - b);
  const stateOf = key => `State.${upper(key)}`;
  const eventOf = key => `Event.${upper(key)}`;
  const outgoing = state => events.filter(event => transitions.some(item => item.state === state.key && item.event === event.key));
  const toOf = (state, event) => transitions.find(item => item.state === state && item.event === event).to;
  const pyBool = value => (value ? 'True' : 'False');
  const lines = [
    header(machine),
    `"""${machine}: the states, the events and the functions of the machine (docs/spec/fsm.md, B-4 and B-6)."""`,
    '',
    'from dataclasses import dataclass',
    'from enum import IntEnum',
    '',
    'from .fsm import Code, Error',
    '',
    '',
    'class State(IntEnum):',
    `    """The states of ${machine}: the value of each member is its code."""`,
    ...(states.length > 0 ? [''] : []),
    ...states.map(state => `    ${upper(state.key)} = ${state.code}`),
    '',
    '',
    'class Event(IntEnum):',
    `    """The events of ${machine}: the value of each member is its position in the declaration, from 1."""`,
    ...(events.length > 0 ? [''] : []),
    ...events.map((event, index) => `    ${upper(event.key)} = ${index + 1}`),
    '',
    '',
    '@dataclass(frozen=True)',
    'class Step:',
    '    """The result of apply: the state that the event leads to, and whether the stored state changed."""',
    '',
    '    to: State',
    '    changed: bool',
    '',
    '',
    `def _unknown_state(value):`,
    '    return Error(',
    '        Code.UNKNOWN_CODE,',
    `        ${message(`${machine}: %s is not a state of ${machine}`, ['value'])},`,
    '    )',
    '',
    '',
    'def _invalid_transition(expected, event):',
    '    return Error(',
    '        Code.INVALID_TRANSITION,',
    `        ${message(`${machine}: the event %s has no edge from %s`, ['event', 'expected'])},`,
    '        expected=expected,',
    '        event=event,',
    '    )',
    '',
    '',
    'def initial() -> State:',
    `    """The initial state of ${machine}."""`,
    `    return ${stateOf(initial)}`,
    '',
    '',
    'def code(state: State) -> int:',
    '    """The code of a state, which is its value; E_UNKNOWN_CODE for a value that is no state."""',
    '    match state:',
    ...states.flatMap(state => [`        case ${stateOf(state.key)}:`, `            return ${state.code}`]),
    '        case _:',
    '            raise _unknown_state(state)',
    '',
    '',
    'def key(state: State) -> str:',
    '    """The key of a state."""',
    '    match state:',
    ...states.flatMap(state => [`        case ${stateOf(state.key)}:`, `            return ${quoted(state.key)}`]),
    '        case _:',
    '            raise _unknown_state(state)',
    '',
    '',
    'def from_code(value: int) -> State:',
    '    """The state of a code: E_RESERVED_CODE for a reserved code, E_UNKNOWN_CODE for any other value."""',
    '    if type(value) is not int:',
    '        raise _unknown_state(value)',
    '    match value:',
    ...states.flatMap(state => [`        case ${state.code}:`, `            return ${stateOf(state.key)}`]),
    ...reserved.flatMap(item => [
      `        case ${item}:`,
      '            raise Error(',
      '                Code.RESERVED_CODE,',
      `                ${quoted(`${machine}: code ${item} is reserved and is no state of ${machine}`)},`,
      '            )',
    ]),
    '        case _:',
    '            raise _unknown_state(value)',
    '',
    '',
    'def is_final(state: State) -> bool:',
    '    """Whether a state is final."""',
    '    match state:',
    ...states.flatMap(state => [`        case ${stateOf(state.key)}:`, `            return ${pyBool(state.final)}`]),
    '        case _:',
    '            raise _unknown_state(state)',
    '',
    '',
    'def events_from(state: State) -> list[Event]:',
    '    """The events that have an edge from a state, in declaration order."""',
    '    match state:',
    ...states.flatMap(state => {
      const list = outgoing(state).map(event => eventOf(event.key));
      return [`        case ${stateOf(state.key)}:`, `            return [${list.join(', ')}]`];
    }),
    '        case _:',
    '            raise _unknown_state(state)',
    '',
    '',
    'def target(expected: State, event: Event) -> State:',
    '    """The state that an event leads to from the expected state; E_INVALID_TRANSITION when the event has no edge from it."""',
    '    match expected:',
    ...states.flatMap(state => {
      const edges = outgoing(state);
      if (edges.length === 0) return [`        case ${stateOf(state.key)}:`, '            raise _invalid_transition(expected, event)'];
      return [
        `        case ${stateOf(state.key)}:`,
        '            match event:',
        ...edges.flatMap(edge => [`                case ${eventOf(edge.key)}:`, `                    return ${stateOf(toOf(state.key, edge.key))}`]),
        '                case _:',
        '                    raise _invalid_transition(expected, event)',
      ];
    }),
    '        case _:',
    '            raise _unknown_state(expected)',
    '',
    '',
    'def apply(expected: State, event: Event, actual: State) -> Step:',
    '    """Applies an event that the observed state expected leads to, when the stored state is actual (docs/spec/fsm.md, B-4)."""',
    '    to = target(expected, event)',
    '    code(actual)',
    '    if actual == expected:',
    '        return Step(to=to, changed=True)',
    '    if actual == to:',
    '        return Step(to=to, changed=False)',
    '    raise Error(',
    '        Code.CONFLICT,',
    `        ${message(`${machine}: the stored state %s is neither %s nor %s`, ['actual', 'expected', 'to'])},`,
    '        expected=expected,',
    '        actual=actual,',
    '        event=event,',
    '    )',
  ];
  return text(lines);
}

/** The native data module tests/vectors.py of `vectorList`, the vectors of every machine in order: `vectors = [...]`. */
/** The Python int literal of a decimal string of the oracle; a value that is no decimal string is an Error. */
function digits(value) {
  if (typeof value !== 'string' || !/^-?[0-9]+$/.test(value)) throw new Error(`python: the input ${JSON.stringify(value)} is not a decimal string`);
  return value;
}

/**
 * The Python literal of a typed input of the oracle (input_type: string, bool or float; docs/spec/fsm.md, B-6). An input without a
 * type is a decimal string written as the int it names (digits).
 */
function inputOf(text, type) {
  if (type === undefined) return digits(text);
  if (type === 'string') return JSON.stringify(text);
  if (type === 'bool' && (text === 'true' || text === 'false')) return text === 'true' ? 'True' : 'False';
  if (type === 'float' && /^-?[0-9]+\.[0-9]+$/.test(text)) return text;
  throw new Error(`python: the input ${JSON.stringify(text)} of type ${JSON.stringify(type)} is not a string, bool or float literal`);
}

/** The native test module tests/vectors.py of `list`: the cases of the python kind (forKind), as Python literals. */
export function vectorsFile(list) {
  const vectorList = forKind(list, KIND);
  const literal = (value, indent) => {
    const inner = `${indent}    `;
    if (value === null) return 'None';
    if (value === true) return 'True';
    if (value === false) return 'False';
    if (typeof value === 'number') return String(value);
    if (typeof value === 'string') return JSON.stringify(value);
    if (Array.isArray(value)) {
      if (value.length === 0) return '[]';
      return `[\n${value.map(item => `${inner}${literal(item, inner)},\n`).join('')}${indent}]`;
    }
    const entries = Object.entries(value);
    if (entries.length === 0) return '{}';
    // An input is a decimal string of the oracle, which is written as the Python int it names (the 64-bit range stays exact); a typed
    // input is written as its literal. The input_type of a case is read by its input and is not written.
    const shown = entries.filter(([name]) => name !== 'input_type');
    const item = ([name, entryValue]) => (name === 'input' ? inputOf(entryValue, value.input_type) : literal(entryValue, inner));
    return `{\n${shown.map(entry => `${inner}${JSON.stringify(entry[0])}: ${item(entry)},\n`).join('')}${indent}}`;
  };
  return text([
    header(SHARED),
    '"""The conformance vectors of every machine (conformance/vectors, docs/plans/fsm-v1/plan.md, C-4)."""',
    '',
    `vectors = ${literal(vectorList, '')}`,
  ]);
}

/**
 * The files of the python package `src/polyspec_fsm/` for the machines `irs` (their IRs in definition order) and the lock:
 * `<machine>.py` per machine, then `fsm.py` and `__init__.py`. Each file is { path, content }.
 */
export function files(irs, lock) {
  const out = [];
  for (const ir of irs) {
    if (!Object.hasOwn(lock, ir.machine)) throw new Error(`python: the lock has no entry for machine ${ir.machine}`);
    out.push({ path: `${ir.machine}.py`, content: machinePy(ir, lock) });
  }
  out.push({ path: 'fsm.py', content: FSM_PY });
  out.push({ path: '__init__.py', content: initJs(irs) });
  return out;
}
